import math


def parse_point(text):
    x, y = text.split(",")
    return (int(x), int(y))


def distance(p, q):
    (x1, y1), (x2, y2) = p, q
    return math.hypot(x2 - x1, y2 - y1)


def closest(points, target):
    best = None
    for p in points:
        if best is None or distance(p, target) < distance(best, target):
            best = p
    return best


def bounds(points):
    xs = []
    ys = []
    for x, y in points:
        xs.append(x)
        ys.append(y)
    return ((min(xs), min(ys)), (max(xs), max(ys)))

