def _():
    check_eq(parse_point("3,4"), (3, 4))
    check_eq(parse_point(" 3 , -4 "), (3, -4))

@test("distance")
def _():
    check_eq(distance((0, 0), (3, 4)), 5.0)
    check_near(distance((1, 1), (2, 2)), 1.41421356, 1e-6)

@test("closest")
def _():
    pts = [(5, 5), (1, 2), (-1, 0), (2, 1)]
    check_eq(closest(pts, (0, 0)), (-1, 0))
    check_eq(closest(pts, (2, 2)), (1, 2))
    check_eq(closest([], (0, 0)), None)

@test("bounds")
def _():
    check_eq(bounds([(5, 5), (1, 2), (-1, 0), (2, 7)]), ((-1, 0), (5, 7)))
    check_eq(bounds([(3, 3)]), ((3, 3), (3, 3)))

